WITH cleaned AS (SELECT *, ROUND(units / revenue, 2) AS revenue_per_unit FROM store_sales WHERE sale_date >= DATE '2023-09-11') SELECT CASE WHEN revenue >= 4000 THEN 'LARGE' ELSE 'SMALL' END AS revenue_tier, PERCENTILE_APPROX(revenue_per_unit, 0.5) AS revenue_per_unit_p50, MIN(revenue) AS min_revenue FROM cleaned GROUP BY 1 HAVING MIN(revenue) > 0 ORDER BY revenue_per_unit_p50 DESC NULLS FIRST
